// Some portions generated by Claude

// Plan task M7.1: the route lifecycle contract (workbench.routes) and how bootstrap mounts and disposes a route.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeWindow } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench(window = {}) {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout,
        clearTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        const absolutePath = path.join(scripts, filename);
        vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });
    }
    window.workbench = context.workbench;
    return context.workbench;
}

function fakeRuntime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

function pageResponse(events) {
    return { ok: true, records: events };
}

/** An in-memory stand-in for the worker-backed row store and the NDJSON reader. */
function installTestStream(workbench) {
    workbench.queryStream = {
        scheduleRowStoreMaintenance() {},
        markCurrentRowStoresForRecovery() {},
        async createRowStore() {
            const rows = [];
            return {
                async append(batch) { rows.push(...batch); return rows.length; },
                async read(start, count) { return rows.slice(start, start + count); },
                async count() { return rows.length; },
                async dispose() {}
            };
        },
        async consumeNdjsonResponse(response, options) {
            for (const record of response.records) {
                await options.onRecord(record);
            }
            return { type: 'end' };
        }
    };
}

/** A page document and window just large enough for bootstrap to render a route. */
function page(viewId) {
    const window = new FakeWindow('page', `https://example.test/workbench/repositories/repo-1/${viewId}`);
    const document = {
        location: window.location,
        body: { classList: { add() {} } },
        documentElement: { setAttribute() {} },
        readyState: 'complete',
        getElementById() { return null; }
    };
    window.document = document;
    window.localStorage = { getItem() { return null; }, setItem() {} };
    window.matchMedia = () => ({ matches: false });
    const mount = {
        ownerDocument: document,
        getAttribute(name) {
            return {
                'data-workbench-fetch-page-model': 'true',
                'data-workbench-view': viewId,
                'data-workbench-base-path': '/workbench',
                'data-workbench-repository-id': 'repo-1'
            }[name] || null;
        }
    };
    const events = [
        { type: 'head', version: 1 },
        { type: 'view', id: viewId },
        { type: 'vars', values: ['context'] },
        { type: 'rows', values: [[{ kind: 'iri', value: 'urn:graph' }]] },
        { type: 'end' }
    ];
    return { window, mount, dependencies: { fetch: () => Promise.resolve(pageResponse(events)), runtime: fakeRuntime(), skipScripts: true } };
}

test('registering a definition makes its route known and router-ready', () => {
    const workbench = loadWorkbench();
    const definition = { viewId: 'example', routerReady: true, scripts: () => [], baseScripts: () => [], mount() {} };

    assert.equal(workbench.routes.get('example'), undefined);
    assert.equal(workbench.routes.isRouterReady('example'), false);
    workbench.routes.register(definition);
    assert.equal(workbench.routes.get('example'), definition);
    assert.equal(workbench.routes.isRouterReady('example'), true);
    workbench.routes.register({ ...definition, routerReady: false });
    assert.equal(workbench.routes.isRouterReady('example'), false);
});

